SELECT gen_random_uuid()::text, 'formula', '$a_T, a_N$', 'Tangential and Normal Acceleration', '$a_T = \frac{\vec{v}\cdot\vec{a}}{|\vec{v}|},\qquad a_N = \frac{|\vec{v}\times\vec{a}|}{|\vec{v}|} = \kappa v^2$', NULL, 'The parts of acceleration along the path and toward its centre of curvature.', '[{"symbol":"$\\vec{v}, \\vec{a}$","meaning":"velocity and acceleration"},{"symbol":"$\\kappa$","meaning":"curvature"}]'::jsonb, '$a_T^2 + a_N^2 = |\vec{a}|^2$; in uniform circular motion $a_T = 0$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'derivatives of vector functions' AND s."active"), 'Motion', true, 'PENDING', now(), now()
