SELECT gen_random_uuid()::text, 'formula', '$\nabla\times\vec{F}$', 'Curl of a Vector Field', '$\nabla\times\vec{F} = \begin{vmatrix}\hat{i} & \hat{j} & \hat{k}\\ \frac{\partial}{\partial x} & \frac{\partial}{\partial y} & \frac{\partial}{\partial z}\\ P & Q & R\end{vmatrix}$', NULL, 'How much a field swirls around each point.', '[{"symbol":"$\\vec{F} = (P, Q, R)$","meaning":"a vector field"}]'::jsonb, 'The k component is Q_x − P_y, the same as in Green''s theorem.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'curl' AND s."active"), NULL, true, 'PENDING', now(), now()
