SELECT gen_random_uuid()::text, 'formula', '$\nabla\times\nabla f = 0$', 'Curl and Divergence Identities', '$\nabla\times(\nabla f) = \vec{0},\qquad \nabla\cdot(\nabla\times\vec{F}) = 0,\qquad \nabla^2f = f_{xx} + f_{yy} + f_{zz}$', NULL, 'A gradient has no curl, a curl has no divergence; the Laplacian is the divergence of the gradient.', '[{"symbol":"$f$","meaning":"a scalar field"},{"symbol":"$\\vec{F} = (P, Q, R)$","meaning":"a vector field"}]'::jsonb, 'On a simply connected region, $\nabla\times\vec{F} = 0$ means $\vec{F}$ is conservative: $\vec{F} = \nabla f$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'curl' AND s."active"), NULL, true, 'PENDING', now(), now()
