SELECT gen_random_uuid()::text, 'formula', '$\iint\vec{F}\cdot\hat{n}\,dS$', 'Flux Through a Surface', '$\Phi = \iint_S\vec{F}\cdot\hat{n}\,dS = \iint_D\vec{F}\cdot(\vec{r}_u\times\vec{r}_v)\,du\,dv$', NULL, 'How much of a field passes through a surface.', '[{"symbol":"$\\vec{F} = (P, Q, R)$","meaning":"a vector field"},{"symbol":"$\\hat{n}$","meaning":"the chosen unit normal"}]'::jsonb, 'Choose the normal''s direction first; the other choice flips the sign.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'surface integrals' AND s."active"), NULL, true, 'PENDING', now(), now()
