SELECT gen_random_uuid()::text, 'formula', '$\oint(P\,dx + Q\,dy)$', 'Green''s Theorem in the Plane', '$\oint_C(P\,dx + Q\,dy) = \iint_D\left(\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}\right)dA$', NULL, 'A line integral round a closed curve as a double integral over the region inside.', '[{"symbol":"$P, Q$","meaning":"components of a plane field"},{"symbol":"$C$","meaning":"the boundary of D, counterclockwise"}]'::jsonb, 'Clockwise traversal flips the sign.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'green''s theorem' AND s."active"), NULL, true, 'PENDING', now(), now()
