SELECT gen_random_uuid()::text, 'formula', '$A = \frac12\oint(x\,dy - y\,dx)$', 'Area by Green''s Theorem', '$A = \frac12\oint_C(x\,dy - y\,dx)$', NULL, 'The area inside a closed curve from its boundary alone.', '[{"symbol":"$C$","meaning":"the boundary, counterclockwise"}]'::jsonb, 'For a polygon it becomes the shoelace formula.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'green''s theorem' AND s."active"), NULL, true, 'PENDING', now(), now()
