SELECT gen_random_uuid()::text, 'formula', '$\oiint\vec{F}\cdot\hat{n}\,dS$', 'Divergence Theorem (Gauss)', '$\oiint_S\vec{F}\cdot\hat{n}\,dS = \iiint_V\nabla\cdot\vec{F}\,dV$', NULL, 'The flux out of a closed surface equals the total divergence inside.', '[{"symbol":"$\\vec{F} = (P, Q, R)$","meaning":"a vector field"},{"symbol":"$S$","meaning":"the closed surface bounding $V$, normal outward"}]'::jsonb, 'It is how Gauss''s law of electrostatics turns from integral to point form.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'divergence theorem' AND s."active"), NULL, true, 'PENDING', now(), now()
