SELECT gen_random_uuid()::text, 'formula', '$\oint\vec{F}\cdot d\vec{r}$', 'Stokes'' Theorem', '$\oint_C\vec{F}\cdot d\vec{r} = \iint_S(\nabla\times\vec{F})\cdot\hat{n}\,dS$', NULL, 'The circulation round a loop equals the curl flux through any surface it bounds.', '[{"symbol":"$\\vec{F} = (P, Q, R)$","meaning":"a vector field"},{"symbol":"$C$","meaning":"the edge of $S$, by the right-hand rule with $\\hat{n}$"}]'::jsonb, 'Green''s theorem is the flat case; Ampère''s law uses it.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Vector Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'stokes'' theorem' AND s."active"), NULL, true, 'PENDING', now(), now()
